{"schema_version":1,"summary":"Made route_request the sole routing implementation; legacy_route delegates directly, and both dispatchers call route_request.","changes":[{"path":"routing.py","content":"from __future__ import annotations

from collections.abc import Iterable


def route_request(kind: str) -> str:
    routes = {"create": "writer", "read": "reader", "delete": "writer"}
    try:
        return routes[kind]
    except KeyError:
        raise ValueError(f"unsupported request kind: {kind}") from None


def legacy_route(kind: str) -> str:
    return route_request(kind)


def dispatch(event: dict[str, str]) -> str:
    return route_request(event["kind"])


def dispatch_batch(events: Iterable[dict[str, str]]) -> list[str]:
    return [route_request(event["kind"]) for event in events]
